// ============================================================================
// Module:       properties (integration test)
// Description:  Property tests for show control's wire input: any UDP
//               datagram decodes as OSC or is refused, and any bytes parse
//               as a MIDI message or are ignored, without a panic.
//
// Dependencies: anyhow, proptest; strobe-io
// ============================================================================

//! OSC arrives from anything on the network, MIDI from any device (D539).
//!
//! Each property feeds the decoders generated bytes, arbitrary and shaped
//! like the real thing (an OSC address, a type tag string, padding, bundles
//! nested deep), and checks they never panic and never return more
//! messages than the datagram could hold. A failing case is shrunk and kept
//! in `tests/properties.proptest-regressions`, replayed first on every run.

use anyhow::{Result, anyhow};
use proptest::prelude::*;
use proptest::test_runner::{Config, FileFailurePersistence, TestRunner};
use strobe_io::{message, osc};

/// Where shrunk failures are kept, relative to this crate.
const REGRESSIONS: &str = "tests/properties.proptest-regressions";

/// Runs `test` over `strategy` for `cases` generated inputs.
fn check<S: Strategy>(
    cases: u32,
    strategy: S,
    test: impl Fn(S::Value) -> Result<(), TestCaseError>,
) -> Result<()> {
    let mut runner = TestRunner::new(Config {
        cases,
        failure_persistence: Some(Box::new(FileFailurePersistence::Direct(REGRESSIONS))),
        ..Config::default()
    });
    runner.run(&strategy, test).map_err(|e| anyhow!("{e}"))
}

/// Bytes shaped like OSC: addresses, type tags, four-byte padding, bundle
/// headers and element sizes, in any order.
fn osc_bytes() -> impl Strategy<Value = Vec<u8>> {
    let piece = prop_oneof![
        Just(b"/strobe/scene\0\0\0".to_vec()),
        Just(b",ifs\0\0\0\0".to_vec()),
        Just(b",\0\0\0".to_vec()),
        Just(b"#bundle\0".to_vec()),
        Just(vec![0u8; 8]),
        Just(vec![0u8, 0, 0, 16]),
        Just(vec![0x7f, 0xff, 0xff, 0xff]),
        Just(vec![0xff, 0xff, 0xff, 0xf0]),
        any::<[u8; 4]>().prop_map(|b| b.to_vec()),
        prop::collection::vec(any::<u8>(), 0..12),
    ];
    prop::collection::vec(piece, 0..40).prop_map(|parts| parts.concat())
}

#[test]
fn any_datagram_decodes_or_is_refused() -> Result<()> {
    check(
        1024,
        prop_oneof![osc_bytes(), prop::collection::vec(any::<u8>(), 0..512)],
        |bytes| {
            if let Ok(messages) = osc::decode(&bytes) {
                // The smallest message is an address and a type tag, eight bytes.
                prop_assert!(
                    messages.len() <= bytes.len() / 8 + 1,
                    "{} messages from {} bytes",
                    messages.len(),
                    bytes.len()
                );
            }
            Ok(())
        },
    )
}

#[test]
fn any_bytes_parse_as_midi_or_are_ignored() -> Result<()> {
    check(2048, prop::collection::vec(any::<u8>(), 0..8), |bytes| {
        // Some or None are both fine; no panic is the property.
        let _ = message::parse(&bytes);
        Ok(())
    })
}
